{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Perindopril, the highest-transfer analogue (0.97), had an absolute oral bioavailability of 19% ± 7% for the active perindoprilat in young healthy subjects, just below the 20% threshold and indicating low systemic availability after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Oxybutynin, a lipophilic ester-containing drug with high transfer (0.89), showed absolute oral bioavailability of 6.2 ± 1.2% for the IR tablet in healthy volunteers, demonstrating that extensive first-pass metabolism can keep such compounds below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Withaferin A, a steroid with enone and hydroxyl groups, showed poor oral bioavailability in humans; its steroid scaffold and metabolic lability support low F for the steroid-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Estradiol, a steroid hormone, has absolute oral bioavailability of about 5% in humans due to intestinal/hepatic first-pass metabolism, supporting low F for the steroid-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paclitaxel, a lipophilic natural product with high transfer, had oral bioavailability of 13% as a single agent due to P-gp/CYP3A-mediated elimination, supporting low F for a lipophilic, metabolically labile query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "β-Sitosterol, a steroid, had absolute oral bioavailability of 0.41% in healthy volunteers, reinforcing that steroid-like molecules can have very low oral F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show low oral bioavailability (0.4-19%), including steroid scaffolds with extensive first-pass metabolism; the query's budesonide-like steroid/ester structure is expected to have F <20%.",
  "evidence_gaps": [
    "No direct oral bioavailability record for the query molecule itself is present in the evidence set.",
    "One perindopril record in cirrhotic patients reported 30% availability, but this disease-condition value is not representative of normal oral bioavailability and was outweighed by the healthy-subject value.",
    "Exact F for the query may be near the 20% boundary, but the consistent sub-20% measurements across high-transfer analogues support low."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

